import{_ as d,a0 as s,w as u,s as l,ao as a,I as e,x as t,a1 as r,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"如何在 Arch Linux 中安装 DNSCrypt 和 Unbound | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Arch Linux 中安装 DNSCrypt 和 Unbound | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Arch Linux 中安装 DNSCrypt 和 Unbound | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Arch Linux 中安装 DNSCrypt 和 Unbound | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150906 How to Install DNSCrypt and Unbound in Arch Linux","title":"如何在 Arch Linux 中安装 DNSCrypt 和 Unbound","tag":"201509","desc":""},"relativePath":"201509/20150906 How to Install DNSCrypt and Unbound in Arch Linux.md","filePath":"[post].md"}'),i={name:"201509/20150906 How to Install DNSCrypt and Unbound in Arch Linux.md"};function c(y,n,S,b,C,N){const o=s("Link");return u(),l("div",null,[n[16]||(n[16]=a(`<h1 id="如何在-arch-linux-中安装-dnscrypt-和-unbound" tabindex="-1">如何在 Arch Linux 中安装 DNSCrypt 和 Unbound <a class="header-anchor" href="#如何在-arch-linux-中安装-dnscrypt-和-unbound" aria-label="Permalink to “如何在 Arch Linux 中安装 DNSCrypt 和 Unbound”">​</a></h1><p><strong>DNSCrypt</strong> 是一个用于对 DNS 客户端和 DNS 解析器之间通信进行加密和验证的协议。它可以阻止 DNS 欺骗或中间人攻击。 DNSCrypt 可用于大多数的操作系统，包括 Linux，Windows，MacOSX ，Android 和 iOS。而在本教程中我使用的是内核为4.1的 archlinux。</p><p><strong>Unbound</strong> 是用来解析收到的任意 DNS 查询的 DNS 缓存服务器。如果用户请求一个新的查询，unbound 会将其存储到缓存中，并且当用户再次请求相同的请求时，unbound 将采用已经保存的缓存。这将比第一次请求查询更快。</p><p>现在我将尝试安装“DNSCrypt”，以确保 DNS 的通信的安全，并用“Unbound”加速。</p><h3 id="第一步-安装-yaourt" tabindex="-1">第一步 - 安装 yaourt <a class="header-anchor" href="#第一步-安装-yaourt" aria-label="Permalink to “第一步 - 安装 yaourt”">​</a></h3><p>Yaourt 是AUR（ARCH 用户仓库）的辅助工具之一，它可以使用户能够很容易地从 AUR 安装程序。 Yaourt 和 pacman 使用相同的语法，你可以使用 yaourt 安装该程序。下面是安装 yaourt 的简单方法：</p><p>1、 用 nano 或者 vi 编辑 arch 仓库配置文件，存放在“/etc/pacman.conf”中。</p><pre><code>$ nano /etc/pacman.conf
</code></pre><p>2、 在 yaourt 仓库底部添加，粘贴下面的脚本：</p><pre><code>[archlinuxfr]
SigLevel = Never
Server = http://repo.archlinux.fr/$arch
</code></pre><p>3、 用“Ctrl + x”，接着用“Y”保存。</p><p>4、 接着升级仓库数据库并用pacman安装yaourt：</p><pre><code>$ sudo pacman -Sy yaourt
</code></pre><h3 id="第二步-安装-dnscrypt-和-unbound" tabindex="-1">第二步 - 安装 DNSCrypt 和 Unbound <a class="header-anchor" href="#第二步-安装-dnscrypt-和-unbound" aria-label="Permalink to “第二步 - 安装 DNSCrypt 和 Unbound”">​</a></h3><p>DNSCrypt 和 unbound 就在 archlinux 仓库中，你可以用下面的 pacman 命令安装：</p><pre><code>$ sudo pacman -S dnscrypt-proxy unbound
</code></pre><p>接着在安装的过程中按下“Y”。</p><h3 id="第三步-安装-dnscrypt-autoinstall" tabindex="-1">第三步 - 安装 dnscrypt-autoinstall <a class="header-anchor" href="#第三步-安装-dnscrypt-autoinstall" aria-label="Permalink to “第三步 - 安装 dnscrypt-autoinstall”">​</a></h3><p>Dnscrypt-autoinstall 是一个在基于 Linux 的系统上自动安装和配置 DNSCrypt 的脚本。DNSCrypt 在 AUR 中，因此你必须使用“yaourt”命令来安装它。</p><pre><code>$ yaourt -S dnscrypt-autoinstall
</code></pre><p>注意 :</p><p>-S = 这和 pacman -S 安装程序一样。</p><h3 id="第四步-运行-dnscrypt-autoinstall" tabindex="-1">第四步 - 运行 dnscrypt-autoinstall <a class="header-anchor" href="#第四步-运行-dnscrypt-autoinstall" aria-label="Permalink to “第四步 - 运行 dnscrypt-autoinstall”">​</a></h3><p>用 root 权限运行“dnscrypt-autoinstall”来自动配置 DNSCrypt。</p><pre><code>$ sudo dnscrypt-autoinstall
</code></pre><p>下一步中按下“回车”，接着输入&quot;Y&quot;来选择你想使用的 DNS 提供者，我这里使用不带日志和 DNSSEC 的 DNSCrypt.eu。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/DNSCrypt-autoinstall.png" alt="DNSCrypt autoinstall"></p><h3 id="第五步-配置-dnscrypt-和-unbound" tabindex="-1">第五步 - 配置 DNSCrypt 和 Unbound <a class="header-anchor" href="#第五步-配置-dnscrypt-和-unbound" aria-label="Permalink to “第五步 - 配置 DNSCrypt 和 Unbound”">​</a></h3><p>1、 打开 dnscrypt 的“/etc/conf.d/dnscrypt-config” ，确认配置文件中“DNSCRYPT_LOCALIP”指向<strong>本地ip</strong>，“DNSCRYPT_LOCALPORT”根据你本人的意愿配置，我是用的是<strong>40</strong>端口。</p><pre><code>$ nano /etc/conf.d/dnscrypt-config

DNSCRYPT_LOCALIP=127.0.0.1
DNSCRYPT_LOCALIP2=127.0.0.2
DNSCRYPT_LOCALPORT=40
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/DNSCryptConfiguration.png" alt="DNSCrypt Configuration"></p><p>保存并退出。</p><p>2、 现在你用 nano 编辑器编辑“/etc/unbound/”下 unbound 的配置文件：</p><pre><code>$ nano /etc/unbound/unbound.conf
</code></pre><p>3、 在脚本最后添加下面的行：</p><pre><code>do-not-query-localhost: no
forward-zone:
name: &quot;.&quot;
forward-addr: 127.0.0.1@40
</code></pre><p>确保<strong>forward-addr</strong>和DNSCrypt中的“<strong>DNSCRYPT_LOCALPORT</strong>”一致。如你所见，用的是<strong>40</strong>端口。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/UnboundConfiguration.png" alt="Unbound Configuration"></p><p>接着保存并退出。</p><h3 id="第六步-运行-dnscrypt-和-unbound-接着添加到开机启动中" tabindex="-1">第六步 - 运行 DNSCrypt 和 Unbound，接着添加到开机启动中 <a class="header-anchor" href="#第六步-运行-dnscrypt-和-unbound-接着添加到开机启动中" aria-label="Permalink to “第六步 - 运行 DNSCrypt 和 Unbound，接着添加到开机启动中”">​</a></h3><p>请用 root 权限运行 DNSCrypt 和 unbound，你可以用 systemctl 命令来运行：</p><pre><code>$ sudo systemctl start dnscrypt-proxy unbound
</code></pre><p>将服务添加到启动中。你可以运行“systemctl enable”：</p><pre><code>$ sudo systemctl enable dnscrypt-proxy unbound
</code></pre><p>命令将会创建软链接到“/usr/lib/systemd/system/”目录的服务。</p><h3 id="第七步-配置-resolv-conf-并重启所有服务" tabindex="-1">第七步 - 配置 resolv.conf 并重启所有服务 <a class="header-anchor" href="#第七步-配置-resolv-conf-并重启所有服务" aria-label="Permalink to “第七步 - 配置 resolv.conf 并重启所有服务”">​</a></h3><p>resolv.conf 是一个在 linux 中用于配置 DNS 解析器的文件。它是一个由管理员创建的纯文本，因此你必须用 root 权限编辑并让它不能被其他人修改。</p><p>用 nano 编辑器编辑：</p><pre><code>$ nano /etc/resolv.conf
</code></pre><p>并添加本地IP “<strong>127.0.0.1</strong>”。现在用“chattr”命令使他只读：</p><pre><code>$ chattr +i /etc/resolv.conf
</code></pre><p>注意：</p><p>如果你想要重新编辑，用“chattr -i /etc/resolv.conf”加入写权限。</p><p>现在你需要重启 DNSCrypt 和 unbound 和网络；</p><pre><code>$ sudo systemctl restart dnscrypt-proxy unbound netctl
</code></pre><p>如果你看到错误，检查配置文件。</p><h3 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to “测试”">​</a></h3><p>1、 测试 DNSCrypt</p>`,58)),e("p",null,[n[1]||(n[1]=t("你可以通过 ",-1)),r(o,{href:"https://dnsleaktest.com/"},{default:p(()=>[...n[0]||(n[0]=[t("https://dnsleaktest.com/",-1)])]),_:1}),n[2]||(n[2]=t(" 来确认 DNSCrypt，点击“标准测试”或者“扩展测试”，然后等待程序运行结束。",-1))]),n[17]||(n[17]=a(`<p>现在你可以看到 DNSCrypt.eu 就已经与作为 DNS 提供商的 DNSCrypt 协同工作了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/TestingDNSCrypt.png" alt="Testing DNSCrypt"></p><p>2、 测试 Unbound</p><p>现在你应该确保 unbound 可以正确地与“dig”和“drill”命令一起工作。</p><p>这是 dig 命令的结果：</p><pre><code>$ dig linoxide.com
</code></pre><p>我们现在看下结果，“Query time”是“533 msec”：</p><pre><code>;; Query time: 533 msec
;; SERVER: 127.0.0.1#53(127.0.0.1)
;; WHEN: Sun Aug 30 14:48:19 WIB 2015
;; MSG SIZE rcvd: 188
</code></pre><p>再次输入命令，我们看到“Query time”是“0 msec”。</p><pre><code>;; Query time: 0 msec
;; SERVER: 127.0.0.1#53(127.0.0.1)
;; WHEN: Sun Aug 30 14:51:05 WIB 2015
;; MSG SIZE rcvd: 188
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/UnboundTest.png" alt="Unbound Test"></p><p>DNSCrypt 对 DNS 客户端和解析端之间的通讯加密做的很好，并且 Unbound 通过缓存让相同的请求在另一次请求同速度更快。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>DNSCrypt 是一个可以加密 DNS 客户端和 DNS 解析器之间的数据流的协议。 DNSCrypt 可以在不同的操作系统上运行，无论是移动端或桌面端。选择 DNS 提供商还包括一些重要的事情，应选择那些提供 DNSSEC 同时没有日志的。Unbound 可被用作 DNS 缓存，从而加快解析过程，因为 Unbound 将请求缓存，那么接下来客户端请求相同的查询时，unbound 将从缓存中取出保存的值。 DNSCrypt 和 Unbound 是针对安全性和速度的一个强大的组合。</p><hr>`,15)),e("p",null,[n[4]||(n[4]=t("via: ",-1)),r(o,{href:"http://linoxide.com/tools/install-dnscrypt-unbound-archlinux/"},{default:p(()=>[...n[3]||(n[3]=[t("http://linoxide.com/tools/install-dnscrypt-unbound-archlinux/",-1)])]),_:1})]),e("p",null,[n[8]||(n[8]=t("作者：",-1)),r(o,{href:"http://linoxide.com/author/arulm/"},{default:p(()=>[...n[5]||(n[5]=[t("Arul",-1)])]),_:1}),n[9]||(n[9]=t(" 译者：",-1)),r(o,{href:"https://github.com/geekpi"},{default:p(()=>[...n[6]||(n[6]=[t("geekpi",-1)])]),_:1}),n[10]||(n[10]=t(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:p(()=>[...n[7]||(n[7]=[t("wxy",-1)])]),_:1})]),e("p",null,[n[13]||(n[13]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...n[11]||(n[11]=[t("LCTT",-1)])]),_:1}),n[14]||(n[14]=t(" 原创编译，",-1)),r(o,{href:"https://linux.cn/"},{default:p(()=>[...n[12]||(n[12]=[t("Linux中国",-1)])]),_:1}),n[15]||(n[15]=t(" 荣誉推出",-1))])])}const x=d(i,[["render",c]]);export{D as __pageData,x as default};
